#include "KS/SRC/stringx.h"

class Font {
public:
    enum HORIZJUST { HORIZJUST_LEFT };
    enum VERTJUST { VERTJUST_CENTER = 1 };
};

class color32 {
public:
    unsigned int value;
};

class PanelQuad;
class FEManager;

class __attribute__((aligned(16))) PanelAnimManager {
    char data[0x80];
};

class PanelFile {
    char data[0x30];
};

class FrontEnd {
public:
    PanelAnimManager pam;
    PanelFile panel;
    FrontEnd *next;
    stringx path;
    FEManager *manager;

    virtual ~FrontEnd();
    virtual void Add(PanelAnimManager);
    virtual void Update(float);
    virtual void Draw();
    virtual void LoadPanel(bool = false);
    virtual PanelFile *GetPanel();
    virtual void SetPanel(stringx);

protected:
    virtual void SetPQIndices();
};

class TextString {
    char data[0x4c];

public:
    TextString(
        Font *, stringx, float, float, int, float,
        Font::HORIZJUST, Font::VERTJUST, bool, color32
    );
};

class FEManager {
    char padding0[0x15620];

public:
    Font font_hand;

private:
    char padding1[0x20fb];

public:
    color32 white;
};

class HelpbarFE : public FrontEnd {
    enum {
        ARROW_H,
        ARROW_V,
        ARROW_BOTH,
        CROSS,
        TRIANGLE,
        CIRCLE,
        SQUARE,
        BTN_NUM
    };

    PanelQuad *buttons[BTN_NUM];
    TextString *help_text[BTN_NUM];
    bool has_text[BTN_NUM];
    stringx default_text[BTN_NUM];
    bool disabled;

public:
    HelpbarFE(FEManager *, stringx, stringx);
    virtual ~HelpbarFE();
    virtual void Draw();
    virtual void LoadPanel(bool = false);

protected:
    virtual void SetPQIndices();
};

extern stringx ksGlobalTextArray[];
extern const char source_file[];
extern "C" void front_end_cons(
    FrontEnd *, FEManager *, stringx, stringx
) __asm__("cons__8FrontEndP9FEManagerG7stringxT2");

void *operator new(unsigned int, unsigned int, const char *, int);

__asm__(".equ ksGlobalTextArray, 0x003E64D0");
__asm__(".equ source_file, 0x004DD500");
__asm__(".equ cons__8FrontEndP9FEManagerG7stringxT2, 0x001579F8");
__asm__(".equ __10TextStringP4FontG7stringxffifQ24Font9HORIZJUSTQ24Font8VERTJUSTbG7color32, 0x00148150");
__asm__(".equ __nw__FUiUiPCci, 0x002AC578");

HelpbarFE::HelpbarFE(FEManager* man, stringx p, stringx pf_name)
{
    front_end_cons(this, man, p, pf_name);

    float sc_sm = 0.8f;
    color32 color = manager->white;

    default_text[ARROW_H] = ksGlobalTextArray[0];
    default_text[ARROW_V] = ksGlobalTextArray[0];
    default_text[ARROW_BOTH] = ksGlobalTextArray[0];
    default_text[CROSS] = ksGlobalTextArray[6];
    default_text[CIRCLE] = ksGlobalTextArray[7];
    default_text[TRIANGLE] = ksGlobalTextArray[9];
    default_text[SQUARE] = ksGlobalTextArray[8];

    for(int i=0; i<BTN_NUM; i++)
        help_text[i] = new(0, source_file, 0) TextString(
            &manager->font_hand, default_text[i], 0, 0, 0, sc_sm,
            Font::HORIZJUST_LEFT, Font::VERTJUST_CENTER, false, color
        );
}
